<script setup>
import {ref} from 'vue';import {useRouter} from 'vue-router';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';
const router=useRouter(),form=ref({title:'',category:'Retail',job_type:'Part-time',location:'',work_mode:'On-site',pay_amount:'',pay_period:'hourly',hours_per_week:'',description:'',requirements:'',closing_date:''}),error=ref(''),busy=ref(false);async function save(){busy.value=true;error.value='';const {data:{user}}=await supabase.auth.getUser();const payload={...form.value,employer_id:user.id,pay_amount:form.value.pay_amount?Number(form.value.pay_amount):null,hours_per_week:form.value.hours_per_week?Number(form.value.hours_per_week):null,closing_date:form.value.closing_date||null,status:'active'};const {data,error:e}=await supabase.from('jobs').insert(payload).select().single();if(e)error.value=e.message;else router.push('/my-jobs');busy.value=false}
</script>
<template><AppShell title="Post a job" subtitle="Reach motivated student talent"><template #default><div class="form-page"><div><span class="eyebrow">EMPLOYER WORKSPACE</span><h1 class="page-title">Create a job post</h1><p class="page-subtitle">Be clear about the role so students know if it's right for them.</p></div><form class="card" style="margin-top:22px" @submit.prevent="save"><div v-if="error" class="alert error">{{error}}</div><div class="grid grid-2"><div class="field"><label>Job title *</label><input v-model="form.title" class="input" required placeholder="e.g. Weekend Retail Assistant"></div><div class="field"><label>Category *</label><select v-model="form.category" class="input"><option>Retail</option><option>Hospitality</option><option>Tutoring</option><option>Administration</option><option>Technology</option><option>Events</option><option>Customer Service</option><option>Other</option></select></div><div class="field"><label>Job type *</label><select v-model="form.job_type" class="input"><option>Part-time</option><option>Casual</option><option>Internship</option><option>Freelance</option><option>Once-off</option><option>Tutoring</option></select></div><div class="field"><label>Location *</label><input v-model="form.location" class="input" required placeholder="e.g. Bellville, Cape Town"></div><div class="field"><label>Work arrangement</label><select v-model="form.work_mode" class="input"><option>On-site</option><option>Hybrid</option><option>Remote</option></select></div><div class="field"><label>Pay amount (ZAR)</label><input v-model="form.pay_amount" class="input" type="number" min="0" step="0.01" placeholder="e.g. 45"></div><div class="field"><label>Pay period</label><select v-model="form.pay_period" class="input"><option value="hourly">Per hour</option><option value="daily">Per day</option><option value="weekly">Per week</option><option value="monthly">Per month</option><option value="fixed">Fixed amount</option></select></div><div class="field"><label>Hours per week</label><input v-model="form.hours_per_week" class="input" type="number" min="1" max="60" placeholder="e.g. 12"></div><div class="field"><label>Application closing date</label><input v-model="form.closing_date" class="input" type="date"></div></div><div class="field"><label>Job description *</label><textarea v-model="form.description" class="input" required minlength="30" placeholder="Describe the role, responsibilities and what a typical shift looks like…"></textarea></div><div class="field"><label>Requirements and skills</label><textarea v-model="form.requirements" class="input" placeholder="List experience, skills, qualifications or availability needed…"></textarea></div><div class="form-actions"><button type="button" class="btn btn-outline" @click="router.back()">Cancel</button><button class="btn btn-primary" :disabled="busy">{{busy?'Publishing…':'Publish job'}}</button></div></form></div></template></AppShell></template>
<style scoped>.form-page{max-width:850px;margin:auto}.form-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:10px}</style>
